from html import escape
from motion_components import product_drawing

def technical_explorer(products):
 p=products[0]
 tabs=''.join(f'<button role="tab" id="product-tab-{i}" aria-selected="{str(i==0).lower()}" aria-controls="product-preview" tabindex="{0 if i==0 else -1}" data-product="{i}"><span>{escape(p["name"])}</span></button>' for i,p in enumerate(products))
 templates=''.join(f'<template id="product-sketch-{i}">{product_drawing(i)}</template>' for i in range(len(products)))
 return '''<section class="product-universe technical-universe" id="product-universe"><div class="section-heading split"><div><p class="eyebrow">02 / PRODUCT UNIVERSE</p><h2>SPECIFIED WITH PURPOSE.<br>CONNECTED WITH PRECISION.</h2></div><p>Explore the components behind critical systems.<br>From material selection to a project-ready enquiry.</p></div><div class="technical-console"><div class="console-top"><span>UNITED PIPING / PRODUCT EXPLORER</span><span>DRAWING & MATERIAL REFERENCE</span></div><div class="product-explorer"><div class="product-tabs" role="tablist" aria-label="Product categories" aria-orientation="vertical">'''+tabs+'''</div><div id="product-preview" role="tabpanel" aria-labelledby="product-tab-0"><div class="explorer-stage"><div class="explorer-drawing">'''+product_drawing(0)+'''</div></div><div class="explorer-specs"><h3>Pipes</h3><p>Seamless and welded pipes across published industrial material families.</p><a class="text-link" href="/products/pipes/">Explore pipes</a></div></div></div><div class="console-bottom"><span>SCHEMATIC VIEWS · NOT TO SCALE</span><a href="/products/">VIEW COMPLETE PORTFOLIO</a><span>SPECIFICATION SUBJECT TO REVIEW</span></div></div>'''+templates+'''</section>'''

def integrated_services(services):
    captions=['Material preparation','Inspection & testing','Coordinated logistics','Document management']
    alts=['Illustrative abrasive surface treatment of steel','Engineer inspecting a steel pipe with a vernier caliper','Illustrative steel pipe bundles prepared in a warehouse','Illustrative technical drawings and project document binders']
    visuals=''.join(f'<div class="service-photo service-photo-{i}" data-service-photo="{i}" {"" if i==1 else "hidden"} role="img" aria-label="{alts[i]}"></div>' for i in range(4))
    return '<section class="integrated-services" id="beyond-supply"><div class="section-heading split"><div><p class="eyebrow">BEYOND SUPPLY</p><h2>THE MATERIAL IS ONLY<br>THE BEGINNING.</h2></div><p>One coordinated approach to preparation,<br>verification, documentation, and delivery.</p></div><div class="services-editorial"><figure class="service-photography">'+visuals+'<figcaption><span id="service-caption">Inspection & testing</span><span id="service-image-note">Supplied reference image</span></figcaption></figure><div class="service-sequence"><p class="service-intro">From your first specification to the final documentation package, our services connect each stage of industrial procurement.</p>'+''.join(f'<details class="service-step" data-service="{i}" data-caption="{captions[i]}" {"open" if i==1 else ""}><summary><span class="service-node" aria-hidden="true"></span><span>{escape(item["name"])}</span><b aria-hidden="true">+</b></summary><div><p>{escape(item["description"])}</p><a class="text-link" href="/services/{item["slug"]}/">Explore {escape(item["name"].lower())}</a></div></details>' for i,item in enumerate(services))+'</div></div><div class="service-footer"><span>ALIGNED TO YOUR PROJECT REQUIREMENTS</span><a class="button" href="/request-a-quote/">Discuss your project</a></div></section>'

def drawing_library():
 return '<section class="industrial-cinematic" id="industrial-perspective" aria-labelledby="perspective-title"><img class="cinematic-poster" src="/assets/pipe-hero.jpg" width="1536" height="1024" loading="lazy" alt="Light reveals the metallic texture inside a large steel pipe"><video class="cinematic-video" muted loop playsinline preload="none" aria-label="Continuous industrial perspective film" hidden></video><div class="cinematic-copy"><p class="eyebrow">AN INDUSTRIAL PERSPECTIVE</p><h2 id="perspective-title">Precision in detail.<br>Perspective at scale.</h2><p>From the surface of a single component<br>to the systems that connect industries.</p><a class="button secondary" href="/industries/">Explore our industries</a></div><span class="cinematic-caption">MATERIAL · CRAFT · SCALE</span><button class="cinematic-control" type="button" hidden>Pause film</button></section>'


def product_documents(p):
 docs=p.get('technicalDocuments',[])
 return '<section class="product-documents"><div><p class="eyebrow">TECHNICAL RESOURCE DESK</p><h2>REFERENCE. REVIEW. SPECIFY.</h2><p>Keep the published starting information with your project enquiry.</p></div><div class="document-links"><a href="/documents/'+p['id']+'-reference.csv" download><span>Published specification summary</span><small>CSV · Brief-based reference · Engineering review required</small></a>'+''.join('<a href="'+escape(d['url'])+'" download><span>'+escape(d['name'])+'</span><small>'+escape(d.get('status','Reference only'))+'</small></a>' for d in docs)+'<p class="small-note">Manufacturer datasheets and certified drawings are supplied when available against the selected product and project requirements.</p></div></section>'
